def token_bucket_trace(capacity:int,initial:int,refill:int,costs:list[int])->list[int]|None:
    if any(type(x) is not int for x in [capacity,initial,refill,*costs]) or capacity<0 or initial<0 or initial>capacity or refill<0 or any(x<0 for x in costs):return None
    tokens=initial;out=[]
    for i,cost in enumerate(costs):
        if i:tokens=min(capacity,tokens+refill)
        if cost<=tokens:tokens-=cost;out.append(tokens)
        else:out.append(-tokens-1)
    return out
